"use client";

import { Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import { type MaskRevealUpElementId, maskRevealUpTimeline } from "./timeline";

export interface MaskRevealUpProps {
  text: string;
  distance?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single lines and their exits, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<MaskRevealUpElementId>;
}

export function MaskRevealUp(props: MaskRevealUpProps) {
  const {
    text,
    distance = 30,
    fontSize = 72,
    color = "#171717",
    fontWeight = 600,
    speed = 1,
    className,
    timing,
  } = props;
  const glide = useGlide();
  const frame = useSceneFrame() * speed;
  const { durationInFrames } = useSceneConfig();
  // The exit is timed against the composition length without `speed`.
  const tl = useTimeline(maskRevealUpTimeline, props, durationInFrames, timing);

  const lines = text.split("\n");

  const enterEasing = Easing.bezier(0.22, 1, 0.36, 1);
  const exitEasing = Easing.bezier(0.64, 0, 0.78, 0);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.03em",
          lineHeight: 1.1,
          textAlign: "center",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        }}
      >
        {lines.map((line, i) => {
          const enter = tl.get(`line:${i}`);
          const exit = tl.get(`exit:${i}`);
          const enterLocal = frame - enter.start;
          const exitLocal = frame - exit.start;
          const enterDur = enter.length;
          const enterTravel = enter.beat("travel");
          const exitDur = exit.length;
          const exitTravelFrom = exit.beat("travelFrom");

          const enterP = interpolate(enterLocal, [0, enterDur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: enterEasing,
          });

          const exitP = interpolate(exitLocal, [0, exitDur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: exitEasing,
          });

          const opacity = enterP * (1 - exitP);

          const yEnter = interpolate(
            enterLocal,
            [0, enterTravel],
            [distance, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: enterEasing,
            },
          );

          const yExit = interpolate(
            exitLocal,
            [exitTravelFrom, exitDur],
            [0, -22],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: exitEasing,
            },
          );

          const y = yEnter + yExit;
          const moving =
            (enterLocal > 0 && enterLocal < enterTravel) ||
            (exitLocal > exitTravelFrom && exitLocal < exitDur);

          const blurEnter = interpolate(enterLocal, [0, enterDur], [6, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: enterEasing,
          });

          const blurExit = interpolate(exitLocal, [0, exitDur], [0, 6], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: exitEasing,
          });

          const blur = blurEnter + blurExit;

          return (
            <span
              key={i}
              style={{
                display: "block",
                transformOrigin: "50% 50%",
                opacity,
                transform: `translateY(${y}px)${glide(moving)}`,
                filter: `blur(${blur}px)`,
              }}
            >
              {line}
            </span>
          );
        })}
      </span>
    </div>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// When each line rises out of its mask and when it sinks back. Frames on the 30 fps
// scene timeline, after `speed`. The ids are public: a saved `timing` prop
// refers to them.

export type MaskRevealUpElementId = `line:${number}` | `exit:${number}`;

export interface MaskRevealUpTimingProps {
  text: string;
}

/** A line fades in over `ENTER`, travelling for the first `ENTER_TRAVEL`. */
const ENTER = 23;
const ENTER_TRAVEL = 11;
/** A line fades out over `EXIT`, travelling from `EXIT_TRAVEL_FROM` on. */
const EXIT = 16;
const EXIT_TRAVEL_FROM = 8;
const ENTER_STAGGER = 3;
const EXIT_STAGGER = 2;

// The exit is timed to end with the scene. `length` here is the composition
// length in scene frames without `speed`, as the component has always read
// it, so a faster scene still leaves at the end of the composition's frames.
export const maskRevealUpTimeline = defineTimeline<
  MaskRevealUpElementId,
  MaskRevealUpTimingProps
>(({ text }, { length }) => {
  const lines = text.split("\n");
  const enterEnd = ENTER + (lines.length - 1) * ENTER_STAGGER;
  const exitStart = Math.max(
    enterEnd,
    length - EXIT - (lines.length - 1) * EXIT_STAGGER,
  );
  return [
    ...lines.map(
      (item, i): TimelineElement<MaskRevealUpElementId> => ({
        id: `line:${i}`,
        lane: "In",
        label: item,
        start: i * ENTER_STAGGER,
        length: ENTER,
        follows: i > 0 ? `line:${i - 1}` : undefined,
        beats: { travel: ENTER_TRAVEL },
      }),
    ),
    ...lines.map(
      (item, i): TimelineElement<MaskRevealUpElementId> => ({
        id: `exit:${i}`,
        lane: "Out",
        label: item,
        start: exitStart + i * EXIT_STAGGER,
        length: EXIT,
        follows: i > 0 ? `exit:${i - 1}` : `line:${lines.length - 1}`,
        beats: { travelFrom: EXIT_TRAVEL_FROM },
      }),
    ),
  ];
});
